import asyncio
import subprocess
import sys

from app.core.config import Settings


def main() -> int:
    if Settings().eval_use_real_llm:
        from app.agents.evaluation import main as real_evaluation

        return asyncio.run(real_evaluation())
    # The offline report is generated by the suite using audited FakeLLM calls and isolated DBs.
    return subprocess.call([sys.executable, "-m", "pytest", "tests/evals"])


if __name__ == "__main__":
    raise SystemExit(main())
